"""Machine learning and institutional risk score entity."""

from typing import Any, Dict, List, Optional
import uuid
from sqlalchemy import Float, ForeignKey, Index, String, UniqueConstraint
from sqlalchemy.dialects.postgresql import JSONB, UUID
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.models.base import Base, TimestampMixin


class InstitutionRiskScore(Base, TimestampMixin):
    """Institutional risk score and anomaly profile generated by ML intelligence engine."""

    __tablename__ = "institution_risk_scores"

    id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    institution_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), ForeignKey("institutions.id", ondelete="CASCADE"), nullable=False, index=True
    )
    academic_year: Mapped[str] = mapped_column(String(20), nullable=False, index=True)
    risk_score: Mapped[float] = mapped_column(Float, nullable=False, default=0.0, index=True)
    risk_level: Mapped[str] = mapped_column(
        String(20), nullable=False, default="LOW", index=True
    )  # LOW, MEDIUM, HIGH, CRITICAL
    anomaly_score: Mapped[float] = mapped_column(Float, nullable=False, default=0.0)

    contributing_factors: Mapped[List[Dict[str, Any]]] = mapped_column(
        JSONB, default=list, nullable=False
    )
    metrics: Mapped[Dict[str, Any]] = mapped_column(
        JSONB, default=dict, nullable=False
    )
    peer_comparison: Mapped[Dict[str, Any]] = mapped_column(
        JSONB, default=dict, nullable=False
    )
    ghost_student_flags: Mapped[Dict[str, Any]] = mapped_column(
        JSONB, default=dict, nullable=False
    )
    model_version: Mapped[str] = mapped_column(String(50), nullable=False, default="v1.0")

    # Relationships
    institution = relationship("Institution", backref="risk_scores")

    __table_args__ = (
        UniqueConstraint("institution_id", "academic_year", "model_version", name="uq_inst_risk_year_version"),
        Index("ix_inst_risk_scores_year_score", "academic_year", "risk_score"),
    )
